/** newest first */
export const NEWS_SORTED = [...NEWS].sort((a, b) => b.date.localeCompare(a.date))

export const byType = (t: NewsType) => NEWS_SORTED.filter((n) => n.type === t)

export const yearsFor = (items: NewsItem[]) =>
  [...new Set(items.map((n) => n.date.slice(0, 4)))].sort((a, b) => b.localeCompare(a))

export const regionsFor = (items: NewsItem[]) =>
  (["global", "europe", "india", "apac"] as Region[]).filter((r) =>
    items.some((n) => n.regions.includes(r)))

export const tagsFor = (items: NewsItem[]) =>
  [...new Set(items.flatMap((n) => n.tags))].sort()

export const YOUTUBE = "https://www.youtube.com/@eurogriptyres/videos"

